<script setup lang="ts">
const path = computed(() => window.location.origin);

const session = useSessionStore();

const visibility = useDocumentVisibility();

const { refresh } = await useAsyncData("session", () => session.getUser());

watch(visibility, async () => {
  if (visibility.value === "visible") refresh();
});

// Объявляем функцию для выхода из системы и очистки данных пользователя
async function logout() {
  if (!confirm("Вы действительно хотите выйти?")) return;
  const access = useCookie("access");
  const refresh = useCookie("refresh");
  await $fetch.raw("/routes/auth/logout", {
    method: "PATCH",
    body: {
      message: "delete",
      access_token: access.value,
      refresh_token: refresh.value,
    },
  });
  access.value = null;
  refresh.value = null;
  session.$reset();
  return navigateTo("/login");
}
</script>

<template>
  <UPage>
    <UHeader to="/persons">
      <template #title>
        <ElementLogoDiv />
      </template>
      <template #default>
        <UNavigationMenu
          v-if="session.user?.role === 'admin'"
          :items="[
            {
              label: 'Пользователи',
              icon: 'i-lucide-users',
              to: '/users',
            },
          ]"
          variant="link"
        />
      </template>
      <template #right>
        <UButton
          class="rounded-full"
          :label="session.user?.username ?? 'Выйти'"
          color="error"
          icon="i-lucide-log-out"
          @click="logout()"
        />
      </template>
    </UHeader>

    <UMain class="pt-16">
      <slot />
    </UMain>

    <USeparator type="dashed" class="h-px" />

    <UFooter>
      <template #left>
        <p class="text-sm">Copyright © {{ new Date().getFullYear() }}</p>
      </template>

      <template #right>
        <UNavigationMenu
          :items="[
            {
              label: 'OpenAPI',
              to: `${path}/schema/swagger`,
              target: '_blank',
            },
            {
              label: 'GitHub',
              to: 'https://github.com/waldesem/Web-Personal-DB',
              target: '_blank',
            },
          ]"
          variant="link"
        />
      </template>
    </UFooter>
  </UPage>
</template>
